\title{The Deligne Envelope for Chebyshev Polynomials of the Second Kind
and the Structure of GL(2) Triple Correlation Sums}
\author{Aristotle}
\date{2026-07-01}

\begin{document}
\maketitle

\begin{abstract}
We prove the sharp \emph{Deligne envelope} for Chebyshev polynomials of the
second kind: for every degree $k \ge 0$ and every $x \in [-1,1]$ one has
$|U_k(x)| \le k+1$, with equality exactly at the endpoints $x = \pm 1$. Through
the Satake parametrization of Hecke eigenvalues this is precisely the classical
prime-power bound $|\lambda_f(p^k)| \le k+1$ for a normalized Hecke eigenform
$f$, and hence the divisor bound $|\lambda_f(n)| \le d(n)$. We then record the
sharp combinatorial envelope for triple correlation sums: any additive triple
correlation of three sequences bounded by $1$ is bounded by the number of terms,
with equality attained only by constant, non-oscillating sequences. Placed side
by side, the two results give a clean structural diagnosis of the triple
correlation problem for $\mathrm{GL}(2)$: the magnitude of every local ingredient
is already sharp, so the full gap between the trivial bound
$X^{1+\varepsilon}Y$ and the conjectured optimal bound $X^{1/2+\varepsilon}Y$ for
$T_f(X,Y) = \sum_{n<X}\sum_{m<Y}\lambda_f(n)\lambda_f(m)\lambda_f(n+m)$ must come
entirely from sign oscillation driven by Sato--Tate equidistribution.
\end{abstract}

\section{Introduction}

Let $f$ be a normalized Hecke eigenform for $\mathrm{SL}(2,\mathbb{Z})$ ---
holomorphic of weight $k \ge 2$, or a Hecke--Maass cusp form --- with real Hecke
eigenvalues $\lambda_f(n)$. These eigenvalues are multiplicative, and at a prime
$p$ the Ramanujan--Petersson bound gives $|\lambda_f(p)| \le 2$, so one may write
$\lambda_f(p) = 2\cos\theta_p$ for a uniquely determined \emph{Satake angle}
$\theta_p \in [0,\pi]$. The higher prime-power eigenvalues are then
\begin{equation}
\lambda_f(p^k) = \frac{\sin\big((k+1)\theta_p\big)}{\sin\theta_p}
= U_k(\cos\theta_p),
\label{eq:satake}
\end{equation}
where $U_k$ is the $k$-th Chebyshev polynomial of the second kind.

A central object encoding the additive--multiplicative interaction of these
eigenvalues is the \emph{triple correlation sum}
\begin{equation}
T_f(X,Y) = \sum_{n < X}\ \sum_{m < Y}\
\lambda_f(n)\,\lambda_f(m)\,\lambda_f(n+m).
\label{eq:triple}
\end{equation}
The Sato--Tate heuristic and random-matrix theory predict, for any
$\varepsilon > 0$ and $1 \le Y \le X^{1/2-\varepsilon}$, the optimal bound
\begin{equation}
|T_f(X,Y)| \ll_{f,\varepsilon} X^{1/2+\varepsilon}\,Y.
\label{eq:optimal}
\end{equation}
The trivial bound, from $|\lambda_f(n)| \le d(n)$, is of size
$X^{1+\varepsilon}Y$; \eqref{eq:optimal} represents square-root cancellation in
the long variable $n$. We prove two sharp results --- one analytic, one
combinatorial --- pinning down where the difficulty in \eqref{eq:optimal}
resides.

\begin{theorem}[Deligne envelope]\label{thm:A}
For every $k \in \mathbb{N}$ and every $x \in [-1,1]$,
\[
|U_k(x)| \le k+1.
\]
The bound is sharp: $U_k(1) = k+1$ and $U_k(-1) = (-1)^k(k+1)$, so equality in
absolute value holds exactly at the endpoints $x = \pm 1$.
\end{theorem}

By \eqref{eq:satake}, Theorem~\ref{thm:A} is the prime-power eigenvalue bound
$|\lambda_f(p^k)| \le k+1$, and via multiplicativity it yields
$|\lambda_f(n)| \le d(n)$.

\begin{theorem}[Triple envelope and sharpness]\label{thm:B}
Let $f, g, h : \mathbb{N} \to \mathbb{R}$ satisfy $|f(n)|, |g(n)|, |h(n)| \le 1$
for all $n$, and define
\[
S(N) = \sum_{n=0}^{N} f(n)\,g(n+1)\,h(n+2).
\]
Then $|S(N)| \le N+1$ for all $N$. The bound is sharp: the constant sequences
$f \equiv g \equiv h \equiv 1$ give $S(N) = N+1$ for all $N$.
\end{theorem}

\section{Definitions and preliminaries}

\begin{definition}[Chebyshev polynomials of the second kind]
The polynomials $\{U_k\}_{k\ge 0}$ are determined by $U_0(x) = 1$,
$U_1(x) = 2x$, and $U_{k+1}(x) = 2x\,U_k(x) - U_{k-1}(x)$. Equivalently, they
satisfy
\begin{equation}
U_k(\cos\theta)\,\sin\theta = \sin\big((k+1)\theta\big),
\qquad \theta \in \mathbb{R}.
\label{eq:cheb}
\end{equation}
\end{definition}

\begin{definition}[Triple correlation sum]
For $f, g, h : \mathbb{N} \to \mathbb{R}$ and $N \in \mathbb{N}$,
\[
S(N) = \sum_{n=0}^{N} f(n)\,g(n+1)\,h(n+2).
\]
This is the combinatorial skeleton of \eqref{eq:triple}: three factors along an
additive pattern, with the arithmetic weights removed.
\end{definition}

\section{The Deligne envelope (Theorem~\ref{thm:A})}

\begin{lemma}\label{lem:sin}
For every $n \in \mathbb{N}$ and $\theta \in \mathbb{R}$,
$|\sin(n\theta)| \le n\,|\sin\theta|$.
\end{lemma}
\begin{proof}
Induct on $n$; the case $n=0$ is trivial. Assuming the bound for $m$, the
angle-addition formula gives
$\sin((m{+}1)\theta) = \sin(m\theta)\cos\theta + \cos(m\theta)\sin\theta$, so
\[
|\sin((m{+}1)\theta)|
\le |\sin(m\theta)| + |\sin\theta|
\le m|\sin\theta| + |\sin\theta| = (m{+}1)|\sin\theta|,
\]
using $|\cos| \le 1$ and the inductive hypothesis.
\end{proof}

\begin{lemma}\label{lem:cheb}
For all $k \in \mathbb{N}$, $\theta \in \mathbb{R}$,
$U_k(\cos\theta)\sin\theta = \sin((k+1)\theta)$.
\end{lemma}
\begin{proof}
This is the defining identity \eqref{eq:cheb}.
\end{proof}

\begin{lemma}\label{lem:endpoints}
For all $k \in \mathbb{N}$, $U_k(1) = k+1$ and $U_k(-1) = (-1)^k(k+1)$.
\end{lemma}
\begin{proof}
Let $\theta \to 0$ in \eqref{eq:cheb}: $\sin((k{+}1)\theta)/\sin\theta \to k+1$,
so $U_k(1)=k+1$. Let $\theta \to \pi$: with $\cos\theta \to -1$, the ratio tends
to $(-1)^k(k+1)$. Both agree with the standard closed forms of $U_k$ at
$\pm 1$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:A}]
Fix $k$ and $x \in [-1,1]$; set $\theta = \arccos x \in [0,\pi]$, so
$\cos\theta = x$.

\emph{Case 1: $\sin\theta \ne 0$.} By Lemma~\ref{lem:cheb},
$|U_k(\cos\theta)|\,|\sin\theta| = |\sin((k{+}1)\theta)|$. By
Lemma~\ref{lem:sin} with $n=k+1$, this is $\le (k{+}1)|\sin\theta|$. Dividing by
$|\sin\theta| > 0$ gives $|U_k(x)| \le k+1$.

\emph{Case 2: $\sin\theta = 0$.} Then $\cos^2\theta = 1$, so $x = \pm 1$. By
Lemma~\ref{lem:endpoints}, $|U_k(\pm 1)| = k+1$.

Sharpness is Lemma~\ref{lem:endpoints}.
\end{proof}

\begin{corollary}
For a normalized Hecke eigenform $f$ and every prime power $p^k$,
$|\lambda_f(p^k)| \le k+1$.
\end{corollary}
\begin{proof}
Immediate from \eqref{eq:satake} and Theorem~\ref{thm:A}, since
$\cos\theta_p \in [-1,1]$.
\end{proof}

\begin{corollary}[Divisor bound]
For every $n \ge 1$, $|\lambda_f(n)| \le d(n)$.
\end{corollary}
\begin{proof}
Write $n = \prod_i p_i^{k_i}$. Multiplicativity and the previous corollary give
$|\lambda_f(n)| = \prod_i |\lambda_f(p_i^{k_i})| \le \prod_i (k_i+1) = d(n)$.
\end{proof}

\section{The triple correlation envelope (Theorem~\ref{thm:B})}

\begin{proof}[Proof of Theorem~\ref{thm:B}]
By the triangle inequality,
\[
|S(N)| \le \sum_{n=0}^{N} |f(n)|\,|g(n{+}1)|\,|h(n{+}2)| \le \sum_{n=0}^{N} 1
= N+1,
\]
since each factor is at most $1$. For sharpness, take
$f\equiv g\equiv h\equiv 1$: every summand equals $1$, so $S(N)=N+1$.
\end{proof}

\begin{remark}
Equality $|S(N)| = N+1$ forces every term to have unit modulus \emph{and} a
common sign: no cancellation. Any variation of sign strictly lowers the sum.
This mirrors the endpoint sharpness of Theorem~\ref{thm:A}.
\end{remark}

\section{Structural consequences for $T_f(X,Y)$}

Applying the divisor bound termwise to \eqref{eq:triple} gives the
\emph{divisor envelope}
\begin{equation}
|T_f(X,Y)| \le \sum_{n<X}\sum_{m<Y} d(n)\,d(m)\,d(n+m)
\ll_\varepsilon X^{1+\varepsilon}\,Y.
\label{eq:env}
\end{equation}
Theorems~\ref{thm:A} and \ref{thm:B} yield the following diagnosis.
\begin{enumerate}
\item \textbf{Magnitudes are sharp.} The local factors
$\lambda_f(p^k) = U_k(\cos\theta_p)$ attain their maximal magnitude $k+1$ exactly
at $\cos\theta_p = \pm 1$; no size improvement of \eqref{eq:env} is possible.
\item \textbf{Extremality means no oscillation.} The envelope \eqref{eq:env} can
be approached only when the summands fail to oscillate --- the degenerate regime
of the Chebyshev endpoints.
\item \textbf{All progress is cancellation.} The gap between \eqref{eq:env} and
\eqref{eq:optimal} --- a full power of $X$ --- must come entirely from
destructive interference of signs.
\end{enumerate}
The Sato--Tate law makes the Satake angles equidistribute with respect to
$\tfrac{2}{\pi}\sin^2\theta\,d\theta$, under which the endpoints have measure
zero: oscillation is generic. Summing \eqref{eq:triple} first over $n$,
\[
T_f(X,Y) = \sum_{m<Y}\lambda_f(m)\underbrace{\sum_{n<X}\lambda_f(n)
\lambda_f(n+m)}_{C_f(X;m)},
\]
so $T_f(X,Y)$ is an average of shifted convolutions $C_f(X;m)$, and
\eqref{eq:optimal} is tied to uniform square-root cancellation for $C_f(X;m)$
over $m \le Y$.

\section{Future directions}

\begin{conjecture}
For a Hecke eigenform whose Satake angles are not all $0$ or $\pi$, there is
$\delta > 0$ with $|T_f(X,Y)| \le X^{1-\delta}Y\,(XY)^{o(1)}$ for
$1 \le Y \le X^{1/2}$. Equality in the triangle bound forces every summand to
share one sign, which the Sato--Tate distribution of $\sign(\lambda_f(p))$
forbids on a positive-density set of primes; quantifying the destructive
interference converts equidistribution into a power saving.
\end{conjecture}

\begin{conjecture}
The bound $|T_f(X,Y)| \ll_{f,\varepsilon} X^{1/2+\varepsilon}Y$ holds if and only
if the shifted convolutions $\sum_{n<X}\lambda_f(n)\lambda_f(n+h)$ enjoy uniform
square-root cancellation in the shift $h$ on the dyadic average over $h \le Y$.
Summing first over $n$ turns each fixed $m$ into a shifted convolution with shift
$h=m$, so the triple sum inherits exactly their cancellation budget.
\end{conjecture}

\begin{conjecture}
Averaged over Satake angles with the Sato--Tate measure, the second moment of
$U_a(\cos\theta)U_b(\cos\theta)U_{a+b}(\cos\theta)$ is a simple closed form in
$a,b$. Products of Chebyshev polynomials of the second kind linearize under the
semicircle inner product, $\langle U_i, U_j\rangle = \delta_{ij}$, so triple
products collapse to a finite count of representations $i+j=k$.
\end{conjecture}

